#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

ENV_FILE=".env.local"

banner "DearDev Supabase + payments setup"

stage "1/8 Create the project"
say "Supabase holds the catalog, the orders, and the private product files."
open_url "https://supabase.com/dashboard"
step "Click New project, name it (e.g. deardev-shop), set a DB password, pick region Singapore."
step "Wait until the project status is Active."
pause "Press Enter once the project is Active"

stage "2/8 Run the schema SQL"
say "Creates products, product_contains, site_contact, orders + the consume_download() function."
open_url "https://supabase.com/dashboard"
step "Left menu SQL Editor → New query."
step "Open supabase/schema.sql from this repo, copy everything, paste, run it."
step "Run it AGAIN later whenever schema.sql changes — every statement is idempotent."
note "Shop already live? Paste supabase/hardening.sql instead — it only adds the rate-limit"
note "counter and the column grants, and never touches your product rows."
pause "Press Enter after it reports Success"

stage "3/8 Private bucket for the .zip files"
say "Paid files must NEVER be public. Downloads go through short-lived signed URLs."
step "Left menu Storage → New bucket → name: digital-products → Public: OFF → Create."
step "Open the bucket → Upload → upload your product .zip (e.g. movement-system-r6-v1.zip)."
note "Keep the file name simple: no spaces, no __MACOSX folder inside the zip."
pause "Press Enter after the .zip is uploaded"

stage "4/8 Point the product row at the file"
say "/api/checkout refuses to sell a product whose file_path is empty (409)."
step "Table Editor → products → open row prod1."
step "Set file_path = the exact object name you uploaded (e.g. movement-system-r6-v1.zip)."
step "Set price = the price in baht (e.g. 199) and is_active = true. Save."
note "Verify later with: node scripts/check-storage.js"
pause "Press Enter after file_path is saved"

stage "5/8 Public image for the product card"
say "Preview images are public (they are shown before purchase) — the .zip is not."
step "Storage → New bucket → name: product-images → Public: ON → Create."
step "Upload your product preview image, then click it and copy the public URL."
ask PRODUCT_IMAGE_URL "Paste the public image URL (Enter to skip):"
if [[ -n "${PRODUCT_IMAGE_URL:-}" ]]; then
  step "Table Editor → products → prod1 → paste it into image_url → Save."
  write_env REACT_APP_SUPABASE_IMAGE_SEED "$PRODUCT_IMAGE_URL"
  note "You can remove REACT_APP_SUPABASE_IMAGE_SEED from .env.local afterwards; it is only a bookmark."
fi
pause "Press Enter when image_url is set (or you chose to skip)"

stage "6/8 API keys → local .env.local"
say "The frontend needs only the anon key. The service_role key is server-only — never expose it."
open_url "https://supabase.com/dashboard"
step "Project Settings (gear) → API Keys → copy the Project URL and the anon public key."
ask REACT_APP_SUPABASE_URL "Paste Project URL (https://xyz.supabase.co):"
ask REACT_APP_SUPABASE_ANON_KEY "Paste anon public key (eyJ...):"
step "Same page → copy the service_role key (click Reveal)."
ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste service_role key (hidden):"
write_env REACT_APP_SUPABASE_URL "$REACT_APP_SUPABASE_URL"
write_env REACT_APP_SUPABASE_ANON_KEY "$REACT_APP_SUPABASE_ANON_KEY"
write_env SUPABASE_URL "$REACT_APP_SUPABASE_URL"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"

stage "7/8 PromptPay + SlipOK (email optional)"
say "PromptPay proxy must be a phone number (10 digits) or a citizen id (13) — NOT a bank account number."
warn "Whoever decodes the QR sees this proxy and the account holder's real name."
open_url "https://slipok.com"
step "Sign up for SlipOK → create a branch → copy the API key and branch id."
step "IMPORTANT: in LINE LIFF, bind the receiving bank account to that branch (otherwise every check fails with error 1014)."
ask PROMPTPAY_PROXY "PromptPay proxy to receive money (phone number recommended):"
ask_secret SLIPOK_API_KEY "Paste SlipOK API key (hidden):"
ask SLIPOK_BRANCH_ID "Paste SlipOK branch id:"
if [[ -z "${SITE_URL:-}" ]]; then SITE_URL="http://localhost:3000"; fi
ask SITE_URL "Public site URL for links:"
write_env PROMPTPAY_PROXY "$PROMPTPAY_PROXY"
write_env SLIPOK_API_KEY "$SLIPOK_API_KEY"
write_env SLIPOK_BRANCH_ID "$SLIPOK_BRANCH_ID"
write_env SITE_URL "$SITE_URL"

if confirm "Set up transactional email now? (optional — buyers can save the /success link)"; then
  open_url "https://resend.com/api-keys"
  step "Sign up for Resend → verify your domain → create an API key."
  ask_secret RESEND_API_KEY "Paste Resend API key (hidden):"
  ask EMAIL_FROM "From address (e.g. DearDev <shop@yourdomain.com>):"
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  write_env EMAIL_FROM "$EMAIL_FROM"
else
  note "Email skipped — the success page shows the licence + download link to save."
fi

stage "8/8 Vercel environment variables"
say "Every value above must also exist on Vercel (Production + Preview) or /api/* will fail there."
open_url "https://vercel.com/dashboard"
step "Open your project → Settings → Environment Variables."
step "Add EACH key from .env.local, including SUPABASE_SERVICE_ROLE_KEY, PROMPTPAY_PROXY,"
step "SLIPOK_API_KEY, SLIPOK_BRANCH_ID and SITE_URL."
step "Add RESEND_API_KEY + EMAIL_FROM only if you chose to enable email (optional)."
note "Never add a REACT_APP_ prefix to server secrets."
step "Save, then redeploy."
pause "Press Enter when the Vercel env vars are saved"

finish
